import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ChordDiagramAnimationProps = Record<string, any>;

// Deterministic random generator for stable renders
const createPseudoRandom = (seed: number) => {
  let currentSeed = seed;
  return () => {
    const x = Math.sin(currentSeed++) * 10000;
    return x - Math.floor(x);
  };
};

// Math helpers
const polarToCartesian = (centerX: number, centerY: number, radius: number, angleInDegrees: number) => {
  const angleInRadians = (angleInDegrees - 90) * (Math.PI / 180.0);
  return {
    x: centerX + (radius * Math.cos(angleInRadians)),
    y: centerY + (radius * Math.sin(angleInRadians))
  };
};

const describeArc = (x: number, y: number, radius: number, startAngle: number, endAngle: number) => {
  const start = polarToCartesian(x, y, radius, endAngle);
  const end = polarToCartesian(x, y, radius, startAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
  return ["M", start.x, start.y, "A", radius, radius, 0, largeArcFlag, 0, end.x, end.y].join(" ");
};

// Types for generated data
type Region = { id: number; startAngle: number; endAngle: number; color: string; label: string; midAngle: number };
type Chord = { path: string; color: string; opacity: number };

const ChordDiagramAnimation: React.FC<ChordDiagramAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 10,
  mainTitle = "Home-to-work travel",
  subTitle = "within the city network",
  subTitleColor = "#0072A8",
  nodeCount = 24,
  chordDensity = 60,
  palette = [
    "#E63946", "#F4A261", "#E9C46A", "#2A9D8F", "#264653",
    "#8338EC", "#3A86FF", "#FF006E", "#FB5607", "#06D6A0"
  ],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `transparent` : backgroundColor;

  // Layout parameters for 9:16
  const cx = width / 2;
  const cy = height * 0.58; // Push down slightly to make room for titles
  const maxRadius = Math.min(width, height) * 0.35; // Leave room for labels

  // Generate deterministic data
  const { regions, chords } = useMemo(() => {
    const random = createPseudoRandom(42);
    const generatedRegions: Region[] = [];
    const generatedChords: Chord[] = [];

    // 1. Generate Regions (Outer arcs)
    let currentAngle = 0;
    const gapAngle = 1.5;
    const totalGap = nodeCount * gapAngle;
    const availableAngle = 360 - totalGap;

    const mockNames = [
      "Inner North", "South East", "Westside", "Central CBD", "River Port",
      "Heights", "Valley", "Outer Rim", "Industrial Park", "Tech Hub",
      "Eastern Suburbs", "Northern Beaches", "Southern Cross", "Greenbelt", "Airport District"
    ];

    const regionSizes = Array.from({ length: nodeCount }).map(() => random() * 0.8 + 0.2);
    const totalSize = regionSizes.reduce((a, b) => a + b, 0);

    for (let i = 0; i < nodeCount; i++) {
      const sizeRatio = regionSizes[i] / totalSize;
      const angleSpan = sizeRatio * availableAngle;
      const endAngle = currentAngle + angleSpan;

      generatedRegions.push({
        id: i,
        startAngle: currentAngle,
        endAngle: endAngle,
        midAngle: currentAngle + (angleSpan / 2),
        color: palette[Math.floor(random() * palette.length)],
        label: mockNames[i % mockNames.length] + (i > mockNames.length - 1 ? ` ${i}` : "")
      });

      currentAngle = endAngle + gapAngle;
    }

    // 2. Generate Chords (Ribbons)
    for (let i = 0; i < chordDensity; i++) {
      // Pick source and target regions (prefer different regions)
      let sourceIdx = Math.floor(random() * nodeCount);
      let targetIdx = Math.floor(random() * nodeCount);
      if (sourceIdx === targetIdx) {
        targetIdx = (targetIdx + 1) % nodeCount;
      }

      const sourceRegion = generatedRegions[sourceIdx];
      const targetRegion = generatedRegions[targetIdx];

      // Pick points within the regions for the ribbon width
      const sourceWidth = (random() * 0.4 + 0.1) * (sourceRegion.endAngle - sourceRegion.startAngle);
      const targetWidth = (random() * 0.4 + 0.1) * (targetRegion.endAngle - targetRegion.startAngle);

      const sourceStartPoint = sourceRegion.startAngle + (random() * (sourceRegion.endAngle - sourceRegion.startAngle - sourceWidth));
      const sourceEndPoint = sourceStartPoint + sourceWidth;

      const targetStartPoint = targetRegion.startAngle + (random() * (targetRegion.endAngle - targetRegion.startAngle - targetWidth));
      const targetEndPoint = targetStartPoint + targetWidth;

      // Inner radius for chords
      const innerR = maxRadius - 15;

      const p1a = polarToCartesian(cx, cy, innerR, sourceStartPoint);
      const p1b = polarToCartesian(cx, cy, innerR, sourceEndPoint);
      const p2a = polarToCartesian(cx, cy, innerR, targetStartPoint);
      const p2b = polarToCartesian(cx, cy, innerR, targetEndPoint);

      // Ribbon Path: Move to source start, quadratic bezier to target end, line to target start, quadratic bezier to source end, close.
      // Control point is the center of the circle to pull ribbons inwards.
      const path = `M ${p1a.x} ${p1a.y} Q ${cx} ${cy} ${p2b.x} ${p2b.y} L ${p2a.x} ${p2a.y} Q ${cx} ${cy} ${p1b.x} ${p1b.y} Z`;

      // Use source color for the chord
      generatedChords.push({
        path,
        color: sourceRegion.color,
        opacity: random() * 0.4 + 0.3 // Semi-transparent
      });
    }

    return { regions: generatedRegions, chords: generatedChords };
  }, [nodeCount, chordDensity, palette, maxRadius, cx, cy]);

  // --- Animations ---

  // Intro fade/slide for titles
  const titleY = spring({ frame: frame - 5, fps, config: { damping: 14 } });
  const titleOpacity = interpolate(frame, [5, 20], [0, 1], { extrapolateRight: "clamp" });

  // Outer ring drawing
  const ringProgress = spring({
    frame: frame - 20,
    fps,
    config: { damping: 200, mass: 2 }, // Slow smooth draw
    durationInFrames: 60
  });

  // Chords reveal (using a growing circular clip path from center)
  const chordsRevealProgress = spring({
    frame: frame - 45,
    fps,
    config: { damping: 18 },
  });
  const clipRadius = interpolate(chordsRevealProgress, [0, 1], [0, maxRadius]);

  // Labels reveal
  const labelsOpacity = interpolate(frame, [60, 90], [0, 1], { extrapolateRight: "clamp" });

  // Continuous subtle rotation of the entire diagram
  const diagramRotation = interpolate(frame, [0, fps * durationInSeconds], [0, 10]);


  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* --- Titles (Optimized for 9:16 vertical space) --- */}
      <div style={{
        position: "absolute",
        top: height * 0.12,
        left: 0,
        width: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        opacity: titleOpacity,
        transform: `translateY(${interpolate(titleY, [0, 1], [20, 0])}px)`,
        padding: "0 40px",
        boxSizing: "border-box"
      }}>
        <h1 style={{
          fontSize: "64px",
          fontWeight: 800,
          color: "#1a1a1a",
          margin: 0,
          textAlign: "center",
          lineHeight: 1.1,
          letterSpacing: "-0.02em"
        }}>
          {mainTitle}
        </h1>
        <h2 style={{
          fontSize: "52px",
          fontWeight: 700,
          color: subTitleColor,
          margin: "12px 0 0 0",
          textAlign: "center",
          lineHeight: 1.1,
          letterSpacing: "-0.01em"
        }}>
          {subTitle}
        </h2>
      </div>

      {/* --- Main Diagram --- */}
      <AbsoluteFill style={{ transform: `rotate(${diagramRotation}deg)`, transformOrigin: `${cx}px ${cy}px` }}>
        <svg width={width} height={height} style={{ overflow: "visible" }}>
          
          {/* Definition for clipping the chords to reveal them from center */}
          <defs>
            <clipPath id="chords-clip">
              <circle cx={cx} cy={cy} r={clipRadius} />
            </clipPath>
          </defs>

          {/* 1. Chords (Inner Connections) */}
          <g clipPath="url(#chords-clip)">
            {chords.map((chord, i) => (
              <path
                key={`chord-${i}`}
                d={chord.path}
                fill={chord.color}
                opacity={chord.opacity}
                style={{ transition: "none" }}
              />
            ))}
          </g>

          {/* 2. Regions (Outer Ring) */}
          {regions.map((region) => {
            // Animate the end angle to "draw" the arc
            const animatedEndAngle = interpolate(
              ringProgress,
              [0, 1],
              [region.startAngle, region.endAngle],
              { extrapolateRight: "clamp" }
            );

            // Don't draw if progress is practically 0
            if (animatedEndAngle <= region.startAngle + 0.1) return null;

            return (
              <path
                key={`region-${region.id}`}
                d={describeArc(cx, cy, maxRadius, region.startAngle, animatedEndAngle)}
                fill="none"
                stroke={region.color}
                strokeWidth={15}
                strokeLinecap="butt"
                style={{ transition: "none" }}
              />
            );
          })}
        </svg>

        {/* 3. Labels (Positioned absolutely outside SVG for crisper text rendering) */}
        {regions.map((region, i) => {
          const angle = region.midAngle;
          // Calculate position slightly outside the ring
          const labelRadius = maxRadius + 30;
          const pos = polarToCartesian(cx, cy, labelRadius, angle);
          
          // Determine if text needs to be flipped to remain readable
          const isLeftHalf = angle > 180 && angle < 360;
          // Standard rotation aligns text with the ray from center
          let textRotation = angle - 90; 
          
          if (isLeftHalf) {
             textRotation += 180;
          }

          // Stagger label entrance slightly based on angle
          const labelScale = spring({
            frame: frame - 50 - (i * 0.5),
            fps,
            config: { damping: 12 },
          });

          return (
            <div
              key={`label-${region.id}`}
              style={{
                position: "absolute",
                left: pos.x,
                top: pos.y,
                // Center the div on the coordinate
                transform: `translate(-50%, -50%) scale(${labelScale}) rotate(${textRotation}deg)`,
                transformOrigin: "center center",
                whiteSpace: "nowrap",
                fontSize: "16px",
                fontWeight: 600,
                color: "#4a4a4a",
                opacity: labelsOpacity,
                // Alignment based on side
                textAlign: isLeftHalf ? "right" : "left",
                // Adjust anchor point so text flows outwards
                transformStyle: "preserve-3d" // Helps with rendering glitches during rotation
              }}
            >
              <div style={{
                // Shift text itself based on which side it's on to align cleanly
                transform: `translateX(${isLeftHalf ? '-50%' : '50%'})`,
              }}>
                {region.label}
              </div>
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ChordDiagramAnimation;